from odoo import Command, _, fields, models
from odoo.exceptions import UserError

PAYMENT_REQUEST_CATEGORY = 'Solicitud de pago'


class PurchaseOrder(models.Model):
    _inherit = 'purchase.order'

    # Technical names generated by Odoo Studio, kept so the data is reused.
    x_studio_reference = fields.Char(string='Reference', related='requisition_id.reference')
    x_studio_reference_1 = fields.Char(string='Reference', related='requisition_id.reference')

    def action_lotoi_create_payment_request(self):
        """Create the payment request of this order in Approvals.

        Replaces the "Crear solicitud de pago" server action. The amount is
        expressed in the currency of the company.
        """
        self.ensure_one()
        category = self.env['approval.category'].search(
            [('name', '=', PAYMENT_REQUEST_CATEGORY)], limit=1)
        if not category:
            raise UserError(
                _("No se encontró la categoría '%s'.", PAYMENT_REQUEST_CATEGORY))
        date_ref = self.date_order or fields.Date.context_today(self)
        amount = self.currency_id._convert(
            self.amount_total, self.company_id.currency_id, self.company_id, date_ref)
        request = self.env['approval.request'].create({
            'name': _('Solicitud de pago - %s', self.name),
            'category_id': category.id,
            'request_owner_id': self.env.user.id,
            'x_studio_boolean_field_5ec_1jrvqjeec': True,
            'product_line_ids': [Command.create({
                'description': '-',
                'x_studio_many2one_field_858_1js9r52nm': self.partner_id.id,
                'quantity': 1,
                'x_studio_importe': amount,
            })],
        })
        return {
            'type': 'ir.actions.act_window',
            'name': _('Solicitud de pago'),
            'res_model': 'approval.request',
            'view_mode': 'form',
            'res_id': request.id,
            'target': 'current',
        }


class PurchaseOrderLine(models.Model):
    _inherit = 'purchase.order.line'

    x_studio_many2one_field_4sr_1j4ks5e81 = fields.Many2one('uom.uom', string='Unidades')
